    #[test]
    fn test_gmac_multiple_of_key_refresh() {
        let handshake_key = k16("7058375091ead1377158ecb30bea2387");
        let ecdh_secret = k32(
            "3c3af0ecd6331bb16d244f4819de063dc70eac9570ac249286a724d07a375552",
        );

        let data = hx(
            "",
        );

        let crypt_index = 3u8;
        // % GMAC_KEY_REFRESH_KEY_POS == 0
        let key_pos = 0x6b1de0u64;
        let gmac_expected = [0x20, 0xcc, 0xa5, 0xf1];

        let gkcrypt = GKCrypt::new(0, crypt_index, &handshake_key, &ecdh_secret).unwrap();

        let gmac = gkcrypt.gmac(key_pos, &data).unwrap();
        assert_eq!(gmac, gmac_expected);
    }

    // Buffered keystream: the background thread pre-fills the circular buffer;
    // requests inside the buffered range must match direct generation.
    #[test]
    fn test_key_stream_buffered() {
        let handshake_key = HANDSHAKE_KEY_TEST;
        let ecdh_secret = ECDH_SECRET_TEST;

        let gkcrypt = GKCrypt::new(4, 7, &handshake_key, &ecdh_secret).unwrap();

        // Wait until the buffer is fully populated (thread fills 4 chunks).
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        loop {
            let populated = lock(&gkcrypt.shared).key_buf_populated;
            if populated == 4 * KEY_BUF_CHUNK_SIZE as u64 {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "key buf not populated in time"
            );
            std::thread::sleep(std::time::Duration::from_millis(2));
        }

        // In-buffer request (offset 0x30, 0x20 bytes)
        let mut buffered = [0u8; 0x20];
        gkcrypt.get_key_stream(0x30, &mut buffered).unwrap();

        let mut direct = [0u8; 0x20];
        gen_key_stream_raw(gkcrypt.key_base(), gkcrypt.iv(), 0x30, &mut direct).unwrap();
        assert_eq!(buffered, direct);

        // Request spanning the end of the circular buffer (wrap-around)
        let buf_size = 4 * KEY_BUF_CHUNK_SIZE as u64;
        let mut buffered = vec![0u8; 0x100];
        gkcrypt.get_key_stream(buf_size - 0x80, &mut buffered).unwrap();
        let mut direct = vec![0u8; 0x100];
        gen_key_stream_raw(gkcrypt.key_base(), gkcrypt.iv(), buf_size - 0x80, &mut direct).unwrap();
        assert_eq!(buffered, direct);

        // decrypt via the buffered path must match direct keystream XOR
        let clear = hx("00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff");
        let mut enc = clear.clone();
        gkcrypt.encrypt(0x1234, &mut enc).unwrap();
        let mut expected = clear.clone();
        for (i, b) in expected.iter_mut().enumerate() {
            let pos = 0x1234 + i as u64;
            let mut ks = [0u8; 16];
            gen_key_stream_raw(gkcrypt.key_base(), gkcrypt.iv(), (pos / 16) * 16, &mut ks).unwrap();
            *b ^= ks[(pos % 16) as usize];
        }
        assert_eq!(enc, expected);
    }

    #[test]
    fn test_counter_add() {
        let base = k16("ffffffffffffffffffffffffffffffff");
        let mut out = [0u8; 16];
        counter_add(&mut out, &base, 2);
        // carry propagates through all bytes
        assert_eq!(out[0], 0x01);
        assert_eq!(&out[1..], &[0x00; 15][..]);

        let base = k16("2ae1bb3d84dc9aa9c352a4cf3ffb8b72");
        let mut out = [0u8; 16];
        counter_add(&mut out, &base, 0);
        assert_eq!(out, base);

        let mut out = [0u8; 16];
        counter_add(&mut out, &base, 0x123);
        assert_eq!(out[0], base[0] + 0x23);
        assert_eq!(out[1], base[1] + 0x1);
        assert_eq!(&out[2..], &base[2..]);
    }

    // Golden vectors from chiaki-ng test/keystate.c.

    #[test]
    fn test_key_state() {
        let mut state = KeyState::new();

        let pos = state.request_pos(0, true);
        assert_eq!(pos, 0);
        let pos = state.request_pos(0x1337, true);
        assert_eq!(pos, 0x1337);
        let pos = state.request_pos(0xffff0000, true);
        assert_eq!(pos, 0xffff0000);
        let pos = state.request_pos(0x1337, true);
        assert_eq!(pos, 0x100001337);
        let pos = state.request_pos(0xffff1337, true);
        assert_eq!(pos, 0xffff1337);
        let pos = state.request_pos(0x50000000, true);
        assert_eq!(pos, 0x150000000);
        let pos = state.request_pos(0xb0000000, true);
        assert_eq!(pos, 0x1b0000000);
        let pos = state.request_pos(0x00000000, true);
        assert_eq!(pos, 0x200000000);
    }

    #[test]
    fn test_key_state_nocommit() {
        let mut state = KeyState::new();

        let pos = state.request_pos(0, false);
        assert_eq!(pos, 0);
        let pos = state.request_pos(0x1337, false);
        assert_eq!(pos, 0x1337);
        let pos = state.request_pos(0xffff0000, false);
        assert_eq!(pos, 0xffff0000);
        let pos = state.request_pos(0x1337, false);
        assert_eq!(pos, 0x1337);
        let pos = state.request_pos(0xffff1337, false);
        assert_eq!(pos, 0xffff1337);
        let pos = state.request_pos(0x50000000, false);
        assert_eq!(pos, 0x50000000);
        let pos = state.request_pos(0xb0000000, false);
        assert_eq!(pos, 0xb0000000);
        let pos = state.request_pos(0x00000000, false);
        assert_eq!(pos, 0);
    }
